/**
 * Member out-of-office windows. At most one row per (org, user); setting it
 * again replaces the previous one via upsert.
 */
import { and, eq, gt, lte } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, memberAbsences } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { brandId, toMemberAbsence } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/**
 * The delegate to redirect to if `userId` is away right now, or `null` when
 * they are not away or have no delegate. Never chases the delegate's own
 * absence — one hop only.
 */
export async function findActiveDelegate(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<UserId | null> {
  const row = getDb()
    .select({ delegateUserId: memberAbsences.delegateUserId })
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
        lte(memberAbsences.startsAt, now),
        gt(memberAbsences.endsAt, now),
      ),
    )
    .get();

  if (!row || row.delegateUserId === null) return null;
  return brandId<UserId>(row.delegateUserId);
}

export async function setAbsence(
  orgId: OrgId,
  userId: UserId,
  delegateUserId: UserId | null,
  startsAt: IsoTimestamp,
  endsAt: IsoTimestamp,
  note: string | null,
): Promise<MemberAbsence> {
  const stamp = new Date().toISOString();
  const row = getDb()
    .insert(memberAbsences)
    .values({
      id: newId(),
      orgId,
      userId,
      delegateUserId,
      startsAt,
      endsAt,
      note,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: { delegateUserId, startsAt, endsAt, note, updatedAt: stamp },
    })
    .returning()
    .get();

  return toMemberAbsence(row);
}

/** Fine to call when nothing is set — deletes zero or one row. */
export async function clearAbsence(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/** Drops `userId` as a delegate from any absence that named them, without ending the absence itself. */
export async function clearDelegateForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null, updatedAt: new Date().toISOString() })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, userId),
      ),
    )
    .run();
}

