/**
 * Replaces whatever absence `input.userId` had, if any. Only whoever may
 * change members' roles may act on someone else's absence; anyone may set
 * their own.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  if (actor.userId !== input.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  if (!(input.endsAt > input.startsAt)) {
    throw new Error("endsAt must be after startsAt");
  }

  if (input.delegateUserId !== null) {
    if (input.delegateUserId === input.userId) {
      throw new Error("A member cannot delegate to themselves");
    }
    await requireActiveMember(input.orgId, input.delegateUserId);
  }

  return absenceRepo.setAbsence(
    input.orgId,
    input.userId,
    input.delegateUserId,
    input.startsAt,
    input.endsAt,
    input.note,
  );
}

/** Clearing when nothing is set is a no-op, not an error. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  if (actor.userId !== userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  await absenceRepo.clearAbsence(orgId, userId);
}

/**
 * Anyone in the workspace may look up anyone else's absence. Resolves to
 * `null` once the window has ended (or when none was ever set) — a
 * not-yet-started absence still resolves to its stored row.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  await requireActiveMember(orgId, userId);

  const stored = await absenceRepo.findAbsence(orgId, userId);
  if (!stored) return null;

  const now = toIsoTimestamp(new Date());
  return stored.endsAt > now ? stored : null;
}

/** Active-member lookup shared by every absence operation. */
async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

