import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as absenceRepo from "@/server/repositories/absence-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import { toIsoTimestamp } from "@/types/common";
import type { IssueId, OrgId, Page, ProjectId, UserId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueWithRelations } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Redirects a would-be assignee to their delegate when they are away right
 * now, unless the actor is assigning the issue to themselves (never
 * redirected) — and never chases the delegate's own absence.
 */
async function resolveAssigneeId(
  actor: Actor,
  orgId: OrgId,
  assigneeId: UserId | null,
): Promise<UserId | null> {
  if (assigneeId === null || assigneeId === actor.userId) return assigneeId;

  const now = toIsoTimestamp(new Date());
  const delegateId = await absenceRepo.findActiveDelegate(orgId, assigneeId, now);
  return delegateId ?? assigneeId;
}

