import { PermissionDeniedError } from "@/lib/permissions";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("absence-scratch", "growth");
});

afterAll(() => {
  cleanup();
});

describe("scratch: absence/delegate", () => {
  it("sets, reads and clears own absence", async () => {
    const absence = await memberService.setAbsence(tenant.actors.member, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: "2020-01-01T00:00:00.000Z",
      endsAt: "2020-01-10T00:00:00.000Z",
      note: "vacation",
    });
    expect(absence.delegateUserId).toBe(tenant.userIds.admin);

    const read = await memberService.getAbsence(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(read).not.toBeNull();

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    const afterClear = await memberService.getAbsence(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(afterClear).toBeNull();

    // clearing again is a no-op
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
  });

  it("rejects setting someone else's absence without permission", async () => {
    await expect(
      memberService.setAbsence(tenant.actors.viewer, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt: "2020-01-01T00:00:00.000Z",
        endsAt: "2020-01-10T00:00:00.000Z",
        note: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("rejects endsAt <= startsAt", async () => {
    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt: "2020-01-10T00:00:00.000Z",
        endsAt: "2020-01-01T00:00:00.000Z",
        note: null,
      }),
    ).rejects.toThrow();
  });

  it("rejects delegate === member", async () => {
    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: tenant.userIds.member,
        startsAt: "2020-01-01T00:00:00.000Z",
        endsAt: "2020-01-10T00:00:00.000Z",
        note: null,
      }),
    ).rejects.toThrow();
  });

  it("rejects a non-member as target or delegate", async () => {
    const other = await createTenant("absence-scratch-other", "growth");
    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("redirects a new assignment to the delegate while away, but not for self-assign", async () => {
    const now = new Date();
    const startsAt = new Date(now.getTime() - 60_000).toISOString();
    const endsAt = new Date(now.getTime() + 60_000).toISOString();

    await memberService.setAbsence(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      delegateUserId: tenant.userIds.admin,
      startsAt,
      endsAt,
      note: null,
    });

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Away redirect on create",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.admin);

    const reassigned = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.viewer,
    });
    expect(reassigned.assigneeId).toBe(tenant.userIds.admin);

    // Self-assign is never redirected, even though the viewer is away.
    const selfAssigned = await issueService.assignIssue(tenant.actors.viewer, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.viewer,
    });
    expect(selfAssigned.assigneeId).toBe(tenant.userIds.viewer);

    await memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer);
  });

  it("redirects overdue alerts and adds the delegate to mention alerts while away", async () => {
    const now = new Date();
    const startsAt = new Date(now.getTime() - 60_000).toISOString();
    const endsAt = new Date(now.getTime() + 60_000).toISOString();

    await memberService.setAbsence(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      delegateUserId: tenant.userIds.admin,
      startsAt,
      endsAt,
      note: null,
    });

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Overdue redirect target" }),
    );

    const occurredAt = now.toISOString();
    await emit("issue.overdue", {
      orgId: tenant.org.id,
      actorId: null,
      occurredAt: occurredAt as never,
      issueId: issue.id,
      projectId: issue.projectId,
      dueAt: occurredAt as never,
      assigneeId: tenant.userIds.viewer,
    });

    const forViewer = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["issue_overdue"],
      limit: 25,
      cursor: null,
    });
    const forAdmin = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_overdue"],
      limit: 25,
      cursor: null,
    });
    expect(forViewer.items).toHaveLength(0);
    expect(forAdmin.items).toHaveLength(1);

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: occurredAt as never,
      commentId: "cmt-scratch-1" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.viewer],
    });

    const mentionForViewer = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });
    const mentionForAdmin = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });
    expect(mentionForViewer.items).toHaveLength(1);
    expect(mentionForAdmin.items).toHaveLength(1);

    await memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer);
  });

  it("drops the delegate when the delegate member is removed, keeping the absence", async () => {
    const other = await createTenant("absence-scratch-removal", "growth");

    await memberService.setAbsence(other.actors.owner, {
      orgId: other.org.id,
      userId: other.userIds.member,
      delegateUserId: other.userIds.admin,
      startsAt: "2020-01-01T00:00:00.000Z",
      endsAt: "2099-01-01T00:00:00.000Z",
      note: null,
    });

    const adminMember = await (await import("@/server/repositories/member-repository")).findMember(
      other.org.id,
      other.userIds.admin,
    );
    if (!adminMember) throw new Error("fixture admin missing");

    await memberService.removeMember(other.actors.owner, {
      orgId: other.org.id,
      memberId: adminMember.id,
    });

    const remaining = await memberService.getAbsence(
      other.actors.owner,
      other.org.id,
      other.userIds.member,
    );
    expect(remaining).not.toBeNull();
    expect(remaining?.delegateUserId).toBeNull();
  });
});

